ee:variables.ee:set-variable:
%dw 2.0
output application/java
var results = vars.rsResults default []
var providers = results filter ((r) -> (r.source default '') startsWith 'provider')
var others = results filter ((r) -> not ((r.source default '') startsWith 'provider'))
---
{ (others map ((r) -> { (r.source): if (r.ok default false) 'OK' else 'UNAVAILABLE' })) }
  ++ (if (isEmpty(providers)) {} else { providers: "$(sizeOf(providers filter ((p) -> p.ok default false))) of $(sizeOf(providers))" })
